mkitem!{mkenum!{# [doc = " A trait error with most of its information removed. This is the error"] # [doc = " returned by an `ObligationCtxt` by default, and suitable if you just"] # [doc = " want to see if a predicate holds, and don't particularly care about the"] # [doc = " error itself (except for if it's an ambiguity or true error)."] # [doc = ""] # [doc = " use `ObligationCtxt::new_with_diagnostics` to get a `FulfillmentError`."] # [derive (Clone , Debug)] pub enum ScrubbedTraitError < 'tcx > { # [doc = " A real error. This goal definitely does not hold."] TrueError , # [doc = " An ambiguity. This goal may hold if further inference is done."] Ambiguity , # [doc = " An old-solver-style cycle error, which will fatal. This is not"] # [doc = " returned by the new solver."] Cycle (PredicateObligations < 'tcx >) , }}}
mkitem!{mkimpl!{impl < 'tcx > ScrubbedTraitError < 'tcx > { pub fn is_true_error (& self) -> bool { match self { ScrubbedTraitError :: TrueError => true , ScrubbedTraitError :: Ambiguity | ScrubbedTraitError :: Cycle (_) => false , } } }}}
mkitem!{mktrait!{pub trait TraitEngine < 'tcx , E : 'tcx > : 'tcx { # [doc = " Requires that `ty` must implement the trait with `def_id` in"] # [doc = " the given environment. This trait must not have any type"] # [doc = " parameters (except for `Self`)."] fn register_bound (& mut self , infcx : & InferCtxt < 'tcx > , param_env : ty :: ParamEnv < 'tcx > , ty : Ty < 'tcx > , def_id : DefId , cause : ObligationCause < 'tcx > ,) { let trait_ref = ty :: TraitRef :: new (infcx . tcx , def_id , [ty]) ; self . register_predicate_obligation (infcx , Obligation { cause , recursion_depth : 0 , param_env , predicate : trait_ref . upcast (infcx . tcx) , } ,) ; } fn register_predicate_obligation (& mut self , infcx : & InferCtxt < 'tcx > , obligation : PredicateObligation < 'tcx > ,) ; fn register_predicate_obligations (& mut self , infcx : & InferCtxt < 'tcx > , obligations : PredicateObligations < 'tcx > ,) { for obligation in obligations { self . register_predicate_obligation (infcx , obligation) ; } } # [must_use] fn select_where_possible (& mut self , infcx : & InferCtxt < 'tcx >) -> Vec < E > ; fn collect_remaining_errors (& mut self , infcx : & InferCtxt < 'tcx >) -> Vec < E > ; # [must_use] fn select_all_or_error (& mut self , infcx : & InferCtxt < 'tcx >) -> Vec < E > { let errors = self . select_where_possible (infcx) ; if ! errors . is_empty () { return errors ; } self . collect_remaining_errors (infcx) } fn has_pending_obligations (& self) -> bool ; fn pending_obligations (& self) -> PredicateObligations < 'tcx > ; # [doc = " Among all pending obligations, collect those are stalled on a inference variable which has"] # [doc = " changed since the last call to `select_where_possible`. Those obligations are marked as"] # [doc = " successful and returned."] fn drain_stalled_obligations_for_coroutines (& mut self , infcx : & InferCtxt < 'tcx > ,) -> PredicateObligations < 'tcx > ; }}}
